license = { workspace = true }
readme = { workspace = true }

[[bin]]
name = "typst"
path = "src/main.rs"
doc = false

[dependencies]
typst = { workspace = true }
typst-bundle = { workspace = true }
typst-eval = { workspace = true }
typst-layout = { workspace = true }
typst-html = { workspace = true }
typst-macros = { workspace = true }
typst-pdf = { workspace = true }
typst-render = { workspace = true }
typst-svg = { workspace = true }
typst-timing = { workspace = true }
typst-utils = { workspace = true }
chrono = { workspace = true }
clap = { workspace = true, features = ["string"] }
clap_complete = { workspace = true }
codespan-reporting = { workspace = true }
color-print = { workspace = true }
comemo = { workspace = true }
dirs = { workspace = true }
ecow = { workspace = true }
fs_extra = { workspace = true }
open = { workspace = true }
parking_lot = { workspace = true }
pathdiff = { workspace = true }
rayon = { workspace = true }
self-replace = { workspace = true, optional = true }
semver = { workspace = true }
serde = { workspace = true }
serde_json = { workspace = true }
serde_yaml = { workspace = true }
shell-escape = { workspace = true }
sigpipe = { workspace = true }
tar = { workspace = true }
tempfile = { workspace = true }
toml = { workspace = true }
xz2 = { workspace = true, optional = true }
zip = { workspace = true, optional = true }

[dependencies.typst-kit]
workspace = true
features = [
    "bundle",
    "embedded-fonts",
    "scan-fonts",
    "system-packages",
    "universe-packages",
    "datetime",
    "emit-diagnostics",
    "system-downloader",
    "watcher",
    "timer",
]

[dev-dependencies]
typst-dev-assets = { workspace = true }
memchr = { workspace = true }
tempfile = { workspace = true }

[build-dependencies]
chrono = { workspace = true }
clap = { workspace = true, features = ["string"] }
clap_complete = { workspace = true }
clap_mangen = { workspace = true }
color-print = { workspace = true }
semver = { workspace = true }
serde = { workspace = true }
typst-utils = { workspace = true }

[features]
default = ["embedded-fonts", "http-server"]

# Embeds some fonts into the binary, see typst-kit
embedded-fonts = ["typst-kit/embedded-fonts"]

# Enables the built-in HTTP server for `typst watch` and HTML export.
http-server = ["typst-kit/http-server"]

# Permits the CLI to update itself without a package manager.
self-update = ["dep:self-replace", "dep:xz2", "dep:zip"]

# Whether to vendor OpenSSL. Not applicable to Windows and macOS builds.
vendor-openssl = ["typst-kit/vendor-openssl"]

[lints]
workspace = true

